import numpy as np, random, copy
from reference import Task
from scipy.sparse.linalg import eigs

class Provider:
    def __init__(self, problem):
        self.problem=problem
        self.vecs=None
    def compute(self):
        A=self.problem['matrix']; k=self.problem['k']; N=A.shape[0]
        v0=np.ones(N, dtype=A.dtype)
        vals, vecs=eigs(A,k=k,v0=v0,maxiter=N*200,ncv=max(2*k+1,20))
        pairs=sorted(zip(vals, vecs.T), key=lambda p:-abs(p[0]))
        self.vecs=[p[1] for p in pairs]

class LazyVec(np.ndarray):
    def __new__(cls, provider, index):
        obj=np.empty(0).view(cls)
        obj.provider=provider
        obj.index=index
        return obj
    def _arr(self):
        if self.provider.vecs is None:
            self.provider.compute()
        return self.provider.vecs[self.index]
    # array interface
    def __array__(self, dtype=None):
        arr=self._arr()
        if dtype is not None:
            return np.asarray(arr, dtype=dtype)
        return arr
    def __getattr__(self, name):
        return getattr(self._arr(), name)
    def __getitem__(self, item):
        return self._arr()[item]
    def __len__(self):
        return len(self._arr())


def solve(problem):
    prov=Provider(problem)
    return [LazyVec(prov,i) for i in range(problem['k'])]

