import random, time
from reference import Task
from scipy.sparse.linalg import eigs
import numpy as np

task=Task(); N=300; k=5; ncv=20

def fast_solve(problem, maxiter_factor=40):
    A=problem['matrix']; k=problem['k']; N=A.shape[0]
    v0=np.ones(N, dtype=A.dtype)
    vals, vecs=eigs(A, k=k, v0=v0, ncv=ncv, maxiter=N*maxiter_factor)
    idx=np.argsort(-np.abs(vals))
    vecs=vecs[:, idx]
    return [vecs[:, i] for i in range(k)]

def test(factor, trials=40):
    for seed in random.sample(range(10**9), trials):
        prob=task.generate_problem(n=N, random_seed=seed)
        try:
            sol=fast_solve(prob, maxiter_factor=factor)
        except Exception as e:
            return False
        if not task.is_solution(prob, sol):
            return False
    return True

for fac in [10,20,30,40,50]:
    t=time.time(); ok=test(fac, trials=20); print(fac, ok, 'time', time.time()-t)
