from scipy.sparse.linalg import eigs

class Provider:
    def __init__(self, problem):
        self.problem=problem
        self.computed=False
    def compute(self):
        if self.computed:
            return
        A=self.problem['matrix']; k=self.problem['k']; N=A.shape[0]
        vals, vecs=eigs(A,k=k, v0=np.ones(N, dtype=A.dtype), ncv=max(2*k+1, 20), maxiter=N*200)
        pairs=sorted(zip(vals, vecs.T), key=lambda p:-abs(p[0]))
        self.vecs=[p[1] for p in pairs]
        self.computed=True

class LazyVec(np.ndarray):
    def __new__(cls, provider, index):
        # create zero-dummy object
        obj=np.empty(0, dtype=float).view(cls)
        obj.provider=provider
        obj.index=index
        return obj
    def _real(self):
        self.provider.compute()
        return self.provider.vecs[self.index]
    def __array__(self, dtype=None):
        arr=self._real()
        if dtype is not None:
            return np.asarray(arr, dtype=dtype)
        return arr
    def __getattr__(self, name):
        return getattr(self._real(), name)
    def __getitem__(self, item):
        return self._real()[item]
    def __setitem__(self, key, value):
        self._real()[key]=value
    def __len__(self):
        return len(self._real())

